// 项目实战“复刻面试自习室”第 18 关：部署上线。
// 学习卡片由 .sites-runtime/cards/pj-deploy-*.mjs 生成（node .sites-runtime/lessons.mjs apply …），题目直接写在这里。
import type {AiLevel} from '../journey';

export const pjDeploy:AiLevel={id:'pj-deploy',title:'部署上线',summary:'为生产环境做准备：健康检查连数据库、HTTPS 下的 Secure Cookie；用 Docker 打包、GitHub Actions 自动测试，部署到服务器并用 Caddy 提供 HTTPS',lessons:[
  {title:'这一关做什么：部署上线',body:'到现在为止，项目只在你自己的电脑上运行，别人访问不到。“部署”就是把它放到一台一直开着、有公网地址的服务器上，让任何人都能用浏览器打开。\n这一关做四件事：\n一、为上线做准备：健康检查要真的检查数据库；HTTPS 下会话 Cookie 要加上 Secure；\n二、写 Dockerfile，把程序和运行环境打包成一个“镜像”，在哪台机器上运行都一样；\n三、写一个 GitHub Actions 工作流：每次推送代码，自动跑一遍测试；\n四、真正部署到一台服务器上，用验收脚本检查线上的服务。'},
  {title:'开发环境和生产环境',body:'你电脑上运行的是“开发环境”，服务器上给真实用户用的是“生产环境”。同一份代码，靠环境变量适应不同的环境（第 5 关就开始这样做了）：\n端口 PORT、数据库路径 DB_PATH、大模型的密钥、第三方登录的密钥、管理员名单……在服务器上由你或者部署平台设置，绝不写进代码、绝不提交到 Git。\n生产环境还要多注意几件事：\n一、HTTPS：线上一定要用 HTTPS，否则密码和 Cookie 在网络上是明文传输。会话 Cookie 加上 Secure 标记，浏览器只会通过 HTTPS 发送它；\n二、数据：SQLite 的数据库文件要放在不会丢的地方，并且定期备份；\n三、出错时只告诉用户“服务器内部错误”，详细信息只写进日志（第 5 关已经这样做了）；\n四、不能让别人下载到不该看到的文件，比如数据库文件、.env 文件。'},
  {title:'健康检查：让平台知道你还活着',body:'第 5 关的 /api/health 一直返回 {"status": "ok"}。部署平台、负载均衡器会定期访问它：返回 200 说明服务正常，连续失败就自动重启或者把流量切走。\n但“进程还在”不等于“能正常工作”。比如数据库文件被删了、磁盘满了，进程还在，所有接口却都在报错。所以健康检查要真的去问一下数据库：执行一条最简单的 SELECT 1，成功才返回 200 {"status": "ok"}；失败返回 503 {"status": "error", "error": "数据库不可用"}。\n503 Service Unavailable 的意思是“服务暂时不可用”，告诉平台：先别把用户送过来。'},
  {title:'Docker：把程序和环境打包在一起',body:'“在我电脑上明明能跑”是部署时最常见的问题：服务器上的语言版本不对、少装了依赖、少了一个文件。\nDocker 的办法是把“程序 + 运行它需要的一切”打包成一个镜像（image）。镜像在任何装了 Docker 的机器上运行起来都一样，运行中的镜像叫容器（container）。\n镜像由 Dockerfile 描述，几个常用的指令：\nFROM：从哪个基础镜像开始，比如官方的 golang、node、python、eclipse-temurin；\nWORKDIR：工作目录；\nCOPY：把文件复制进镜像；\nRUN：构建镜像时执行的命令，比如安装依赖、编译；\nENV：设置环境变量；\nEXPOSE：说明程序监听哪个端口；\nCMD：容器启动时执行的命令。\n“多阶段构建”：先在一个装了编译工具的镜像里编译，再把编译结果复制到一个小得多的镜像里运行，最终的镜像里没有编译器和源代码。'},
  {title:'持续集成：每次推送都自动测试',body:'第 17 关写的测试，要记得跑才有用。持续集成（CI，Continuous Integration）就是让一台服务器替你记着：每次推送代码，自动拉取、安装依赖、跑一遍测试，结果显示在 GitHub 上，失败了还会发邮件提醒你。\nGitHub 自带的 CI 叫 GitHub Actions：在仓库里新建 .github/workflows/ci.yml，用 YAML 格式写清楚“什么时候运行（on）”和“运行哪些步骤（steps）”。公开仓库免费使用。\n再进一步，测试通过后自动部署，叫持续部署（CD）。不同的部署平台做法不同，这一关只做 CI，部署先手动完成。'},
  {title:'任务一：为上线做准备',body:'两处改动：健康检查真的去问一下数据库，不可用时返回 503；会话 Cookie 在设置了 COOKIE_SECURE=true 时加上 Secure（线上用 HTTPS 时设置）。',variants:{go:{practice:{steps:['按代码修改 store.go、auth.go、oauth.go，补完健康检查的 TODO。','go test ./... 确认第 17 关的测试仍然通过。','设置 COOKIE_SECURE=true 启动，用 curl -i 登录一次，看 Set-Cookie 里多了 Secure；不设置时没有。'],expect:'GET /api/health → 200 {"status":"ok"}\nSet-Cookie: session=…; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Lax'},code:'// internal/store/store.go：加一个方法\n// Ping 执行一条最简单的查询，确认数据库能用。\nfunc (s *QuestionStore) Ping() error {\n    var one int\n    return s.db.QueryRow("SELECT 1").Scan(&one)\n}\n\n// internal/handler/auth.go：在 setSession 前面加上这个变量，三处 Cookie 都加上 Secure\n// secureCookies 为 true 时，Cookie 只通过 HTTPS 发送。线上用 HTTPS 时设置 COOKIE_SECURE=true。\nvar secureCookies = os.Getenv("COOKIE_SECURE") == "true"\n\nfunc setSession(w http.ResponseWriter, token string) {\n    http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: token, Path: "/",\n        MaxAge: int(service.SessionTTL.Seconds()), HttpOnly: true, SameSite: http.SameSiteLaxMode,\n        Secure: secureCookies})\n}\n\nfunc clearSession(w http.ResponseWriter) {\n    http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: "", Path: "/",\n        MaxAge: -1, HttpOnly: true, SameSite: http.SameSiteLaxMode, Secure: secureCookies})\n}\n\n// internal/handler/oauth.go：保存 state 的 Cookie 同样加上 Secure: secureCookies\n\n// internal/handler/handler.go：健康检查改成\nfunc (h *Handler) health(w http.ResponseWriter, r *http.Request) {\n    // TODO：调用 h.store.Ping()；出错时记一行日志，返回 503 {"status": "error", "error": "数据库不可用"}；\n    //       正常时和原来一样返回 200 {"status": "ok"}\n}',explain:[{at:'// internal/store/store.go',to:'return s.db.QueryRow("SELECT 1").Scan(&one)',text:'SELECT 1 什么表都不查，只返回数字 1。能执行成功，说明数据库文件在、能打开、能读。'},{at:'// internal/handler/auth.go',to:'var secureCookies = os.Getenv("COOKIE_SECURE") == "true"',text:'从环境变量读一次（auth.go 顶部要 import "os"）。本地用 http://localhost，不设置它；线上用 HTTPS，设置成 true。'},{at:'func setSession(',to:'Secure: secureCookies})',text:'设置和清除会话 Cookie 时都加上 Secure。浏览器只会通过 HTTPS 发送带 Secure 的 Cookie，就算有人诱导浏览器访问 http:// 地址，会话也不会以明文泄露。'},{at:'func clearSession(',to:'Secure: secureCookies})',text:'清除时的属性要和设置时一致。'},{at:'// internal/handler/handler.go：健康检查改成',to:'func (h *Handler) health(',text:'健康检查，要你改写。'},{at:'// TODO',to:'//       正常时',text:'要你补全。'}],solution:{code:'// internal/store/store.go：加一个方法\n// Ping 执行一条最简单的查询，确认数据库能用。\nfunc (s *QuestionStore) Ping() error {\n    var one int\n    return s.db.QueryRow("SELECT 1").Scan(&one)\n}\n\n// internal/handler/auth.go：在 setSession 前面加上这个变量，三处 Cookie 都加上 Secure\n// secureCookies 为 true 时，Cookie 只通过 HTTPS 发送。线上用 HTTPS 时设置 COOKIE_SECURE=true。\nvar secureCookies = os.Getenv("COOKIE_SECURE") == "true"\n\nfunc setSession(w http.ResponseWriter, token string) {\n    http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: token, Path: "/",\n        MaxAge: int(service.SessionTTL.Seconds()), HttpOnly: true, SameSite: http.SameSiteLaxMode,\n        Secure: secureCookies})\n}\n\nfunc clearSession(w http.ResponseWriter) {\n    http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: "", Path: "/",\n        MaxAge: -1, HttpOnly: true, SameSite: http.SameSiteLaxMode, Secure: secureCookies})\n}\n\n// internal/handler/oauth.go：保存 state 的 Cookie 同样加上 Secure: secureCookies\n\n// internal/handler/handler.go：健康检查改成\nfunc (h *Handler) health(w http.ResponseWriter, r *http.Request) {\n    if err := h.store.Ping(); err != nil {\n        log.Printf("健康检查：数据库不可用：%v", err)\n        writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "error", "error": "数据库不可用"})\n        return\n    }\n    writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})\n}',explain:[{at:'// internal/store/store.go',to:'return s.db.QueryRow("SELECT 1").Scan(&one)',text:'SELECT 1 什么表都不查，只返回数字 1。能执行成功，说明数据库文件在、能打开、能读。'},{at:'// internal/handler/auth.go',to:'var secureCookies = os.Getenv("COOKIE_SECURE") == "true"',text:'从环境变量读一次（auth.go 顶部要 import "os"）。本地用 http://localhost，不设置它；线上用 HTTPS，设置成 true。'},{at:'func setSession(',to:'Secure: secureCookies})',text:'设置和清除会话 Cookie 时都加上 Secure。浏览器只会通过 HTTPS 发送带 Secure 的 Cookie，就算有人诱导浏览器访问 http:// 地址，会话也不会以明文泄露。'},{at:'func clearSession(',to:'Secure: secureCookies})',text:'清除时的属性要和设置时一致。'},{at:'// internal/handler/handler.go：健康检查改成',to:'func (h *Handler) health(',text:'健康检查，要你改写。'},{at:'if err := h.store.Ping(); err != nil {',to:'return',text:'数据库不可用：详细原因写日志，给平台的回答是 503 和一句简短的话。'},{at:'writeJSON(w, http.StatusOK,',text:'正常时 200。'}]}},java:{practice:{steps:['新建 config/Cookies.java，按注释给几处 Cookie 加上 secure，改写 HelloController，补完 TODO。','mvnw test 确认第 17 关的测试仍然通过。','设置 COOKIE_SECURE=true 启动，用 curl -i 登录一次，看 Set-Cookie 里多了 Secure；不设置时没有。'],expect:'GET /api/health → 200 {"status":"ok"}\nSet-Cookie: session=…; Path=/; Max-Age=604800; Expires=…; Secure; HttpOnly; SameSite=Lax'},code:'// config/Cookies.java\npackage com.example.zixishi.config;\n\n// 线上用 HTTPS 时设置 COOKIE_SECURE=true，Cookie 只通过 HTTPS 发送\npublic final class Cookies {\n\n    public static final boolean SECURE = "true".equals(System.getenv("COOKIE_SECURE"));\n\n    private Cookies() {}\n}\n\n// AuthController、OAuthController（模板渲染版本还有 LoginPageController）：\n// 每一处 ResponseCookie.from(…).httpOnly(true) 后面加上 .secure(Cookies.SECURE)，并导入 com.example.zixishi.config.Cookies\n\n// controller/HelloController.java：健康检查改成\npackage com.example.zixishi.controller;\n\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.dao.DataAccessException;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.RestController;\n\n@RestController\npublic class HelloController {\n\n    private static final Logger log = LoggerFactory.getLogger(HelloController.class);\n\n    private final JdbcTemplate jdbc;\n\n    public HelloController(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    @GetMapping("/api/health")\n    public ResponseEntity<Map<String, String>> health() {\n        // TODO：jdbc.queryForObject("SELECT 1", Integer.class) 问一下数据库；正常返回 200 {"status": "ok"}；\n        //       出 DataAccessException 时记日志，返回 503 {"status": "error", "error": "数据库不可用"}\n        return ResponseEntity.ok(Map.of("status", "ok"));\n    }\n}',explain:[{at:'// config/Cookies.java',to:'package com.example.zixishi.config;',text:'新建一个小类，放 Cookie 的公共设置。'},{at:'// 线上用 HTTPS 时',to:'private Cookies() {}',text:'SECURE 在类加载时从环境变量读一次。为 true 时，浏览器只会通过 HTTPS 发送 Cookie，就算有人诱导浏览器访问 http:// 地址，会话也不会以明文泄露。私有构造函数表示这个类不用 new，只用里面的常量。'},{at:'// controller/HelloController.java：健康检查改成',to:'import org.springframework.web.bind.annotation.RestController;',text:'健康检查要用到 JdbcTemplate。'},{at:'@RestController',to:'this.jdbc = jdbc;',text:'注入 JdbcTemplate，log 用来写日志。'},{at:'@GetMapping("/api/health")',to:'public ResponseEntity<Map<String, String>> health() {',text:'返回值改成 ResponseEntity，才能在出错时返回 503。下面要你改写。'},{at:'// TODO',to:'return ResponseEntity.ok(Map.of("status", "ok"));',text:'要你补全。'}],solution:{code:'// config/Cookies.java\npackage com.example.zixishi.config;\n\n// 线上用 HTTPS 时设置 COOKIE_SECURE=true，Cookie 只通过 HTTPS 发送\npublic final class Cookies {\n\n    public static final boolean SECURE = "true".equals(System.getenv("COOKIE_SECURE"));\n\n    private Cookies() {}\n}\n\n// AuthController、OAuthController（模板渲染版本还有 LoginPageController）：\n// 每一处 ResponseCookie.from(…).httpOnly(true) 后面加上 .secure(Cookies.SECURE)，并导入 com.example.zixishi.config.Cookies\n\n// controller/HelloController.java：健康检查改成\npackage com.example.zixishi.controller;\n\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.dao.DataAccessException;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.RestController;\n\n@RestController\npublic class HelloController {\n\n    private static final Logger log = LoggerFactory.getLogger(HelloController.class);\n\n    private final JdbcTemplate jdbc;\n\n    public HelloController(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    @GetMapping("/api/health")\n    public ResponseEntity<Map<String, String>> health() {\n        try {\n            jdbc.queryForObject("SELECT 1", Integer.class);\n            return ResponseEntity.ok(Map.of("status", "ok"));\n        } catch (DataAccessException e) {\n            log.error("健康检查：数据库不可用", e);\n            return ResponseEntity.status(503).body(Map.of("status", "error", "error", "数据库不可用"));\n        }\n    }\n}',explain:[{at:'// config/Cookies.java',to:'package com.example.zixishi.config;',text:'新建一个小类，放 Cookie 的公共设置。'},{at:'// 线上用 HTTPS 时',to:'private Cookies() {}',text:'SECURE 在类加载时从环境变量读一次。为 true 时，浏览器只会通过 HTTPS 发送 Cookie，就算有人诱导浏览器访问 http:// 地址，会话也不会以明文泄露。私有构造函数表示这个类不用 new，只用里面的常量。'},{at:'// controller/HelloController.java：健康检查改成',to:'import org.springframework.web.bind.annotation.RestController;',text:'健康检查要用到 JdbcTemplate。'},{at:'@RestController',to:'this.jdbc = jdbc;',text:'注入 JdbcTemplate，log 用来写日志。'},{at:'@GetMapping("/api/health")',to:'public ResponseEntity<Map<String, String>> health() {',text:'返回值改成 ResponseEntity，才能在出错时返回 503。下面要你改写。'},{at:'try {',to:'return ResponseEntity.ok(Map.of("status", "ok"));',text:'SELECT 1 什么表都不查，只返回 1。能执行，说明数据库能用。'},{at:'} catch (DataAccessException e) {',to:'return ResponseEntity.status(503)',text:'数据库不可用：详细原因写日志，给平台的回答是 503 和一句简短的话。'}]}},node:{practice:{steps:['新建 src/cookies.js，按注释修改 auth.js、oauth.js、middleware.js 和 app.js（模板渲染版本还有 app.js 里登录、退出的两处），补完健康检查的 TODO。','node --test 确认第 17 关的测试仍然通过。','设置 COOKIE_SECURE=true 启动，用 curl -i 登录一次，看 Set-Cookie 里多了 Secure；不设置时没有。'],expect:'GET /api/health → 200 {"status":"ok"}\nSet-Cookie: session=…; Max-Age=604800; Path=/; Expires=…; HttpOnly; Secure; SameSite=Lax'},code:'// src/cookies.js\n// 会话 Cookie 的属性集中写在一处。线上用 HTTPS 时设置 COOKIE_SECURE=true，Cookie 只通过 HTTPS 发送\nconst secure = process.env.COOKIE_SECURE === "true";\nconst SESSION_COOKIE = { httpOnly: true, sameSite: "lax", path: "/", secure };\n\nmodule.exports = { secure, SESSION_COOKIE };\n\n// src/routes/auth.js：原来的 const COOKIE = { … } 改成\nconst { SESSION_COOKIE: COOKIE } = require("../cookies");\n\n// src/routes/oauth.js：STATE 加上 secure；回调里设置 session 时改用 { ...SESSION_COOKIE, maxAge: SESSION_TTL }\nconst { secure, SESSION_COOKIE } = require("../cookies");\nconst STATE = { httpOnly: true, sameSite: "lax", path: "/auth", secure };\n\n// src/middleware.js：错误处理中间件改成，请求正文不是合法的 JSON 时返回 400\nfunction errorHandler(err, req, res, next) {\n  if (err.type === "entity.parse.failed") {\n    return res.status(400).json({ error: "请求正文要是 JSON" });\n  }\n  console.error(err);\n  res.status(500).json({ error: "服务器内部错误" });\n}\n\n// app.js：顶部改成同时导入 db\nconst { db, importIfEmpty } = require("./src/db/database");\n\n// app.js：健康检查改成\napp.get("/api/health", (req, res) => {\n  // TODO：执行 db.prepare("SELECT 1").get()；成功返回 { status: "ok" }；\n  //       出错时记一行日志，返回 503 { status: "error", error: "数据库不可用" }\n});',explain:[{at:'// src/cookies.js',to:'module.exports = { secure, SESSION_COOKIE };',text:'新建一个小文件，把会话 Cookie 的属性集中起来，以后要改只改这一处。secure 为 true 时，浏览器只会通过 HTTPS 发送这个 Cookie，就算有人诱导浏览器访问 http:// 地址，会话也不会以明文泄露。'},{at:'// src/routes/auth.js',to:'const { SESSION_COOKIE: COOKIE } = require("../cookies");',text:'“SESSION_COOKIE: COOKIE”是解构时改名：取出 SESSION_COOKIE，在这个文件里还叫 COOKIE，下面的代码不用改。'},{at:'// src/routes/oauth.js',to:'const STATE = { httpOnly: true, sameSite: "lax", path: "/auth", secure };',text:'保存 state 的 Cookie 和登录后的会话 Cookie 也加上 secure。如果你用模板渲染，app.js 里登录、退出页面设置的 Cookie 同样改用 SESSION_COOKIE。'},{at:'// src/middleware.js：错误处理中间件改成',to:'res.status(500).json({ error: "服务器内部错误" });',text:'express.json() 解析失败时会把一个 type 是 "entity.parse.failed" 的错误交给错误处理中间件。这是客户端发错了内容，应该返回 400；原来一律当成 500，线上的监控会以为服务器出了问题。'},{at:'// app.js：顶部改成同时导入 db',to:'const { db, importIfEmpty } = require("./src/db/database");',text:'健康检查要用到数据库连接。'},{at:'// app.js：健康检查改成',to:'app.get("/api/health", (req, res) => {',text:'健康检查，要你改写。'},{at:'// TODO',to:'//       出错时',text:'要你补全。'}],solution:{code:'// src/cookies.js\n// 会话 Cookie 的属性集中写在一处。线上用 HTTPS 时设置 COOKIE_SECURE=true，Cookie 只通过 HTTPS 发送\nconst secure = process.env.COOKIE_SECURE === "true";\nconst SESSION_COOKIE = { httpOnly: true, sameSite: "lax", path: "/", secure };\n\nmodule.exports = { secure, SESSION_COOKIE };\n\n// src/routes/auth.js：原来的 const COOKIE = { … } 改成\nconst { SESSION_COOKIE: COOKIE } = require("../cookies");\n\n// src/routes/oauth.js：STATE 加上 secure；回调里设置 session 时改用 { ...SESSION_COOKIE, maxAge: SESSION_TTL }\nconst { secure, SESSION_COOKIE } = require("../cookies");\nconst STATE = { httpOnly: true, sameSite: "lax", path: "/auth", secure };\n\n// src/middleware.js：错误处理中间件改成，请求正文不是合法的 JSON 时返回 400\nfunction errorHandler(err, req, res, next) {\n  if (err.type === "entity.parse.failed") {\n    return res.status(400).json({ error: "请求正文要是 JSON" });\n  }\n  console.error(err);\n  res.status(500).json({ error: "服务器内部错误" });\n}\n\n// app.js：顶部改成同时导入 db\nconst { db, importIfEmpty } = require("./src/db/database");\n\n// app.js：健康检查改成\napp.get("/api/health", (req, res) => {\n  try {\n    db.prepare("SELECT 1").get();\n    res.json({ status: "ok" });\n  } catch (err) {\n    console.error("健康检查：数据库不可用：", err);\n    res.status(503).json({ status: "error", error: "数据库不可用" });\n  }\n});',explain:[{at:'// src/cookies.js',to:'module.exports = { secure, SESSION_COOKIE };',text:'新建一个小文件，把会话 Cookie 的属性集中起来，以后要改只改这一处。secure 为 true 时，浏览器只会通过 HTTPS 发送这个 Cookie，就算有人诱导浏览器访问 http:// 地址，会话也不会以明文泄露。'},{at:'// src/routes/auth.js',to:'const { SESSION_COOKIE: COOKIE } = require("../cookies");',text:'“SESSION_COOKIE: COOKIE”是解构时改名：取出 SESSION_COOKIE，在这个文件里还叫 COOKIE，下面的代码不用改。'},{at:'// src/routes/oauth.js',to:'const STATE = { httpOnly: true, sameSite: "lax", path: "/auth", secure };',text:'保存 state 的 Cookie 和登录后的会话 Cookie 也加上 secure。如果你用模板渲染，app.js 里登录、退出页面设置的 Cookie 同样改用 SESSION_COOKIE。'},{at:'// src/middleware.js：错误处理中间件改成',to:'res.status(500).json({ error: "服务器内部错误" });',text:'express.json() 解析失败时会把一个 type 是 "entity.parse.failed" 的错误交给错误处理中间件。这是客户端发错了内容，应该返回 400；原来一律当成 500，线上的监控会以为服务器出了问题。'},{at:'// app.js：顶部改成同时导入 db',to:'const { db, importIfEmpty } = require("./src/db/database");',text:'健康检查要用到数据库连接。'},{at:'// app.js：健康检查改成',to:'app.get("/api/health", (req, res) => {',text:'健康检查，要你改写。'},{at:'try {',to:'res.json({ status: "ok" });',text:'SELECT 1 什么表都不查，只返回 1。能执行，说明数据库能用。'},{at:'} catch (err) {',to:'res.status(503).json({ status: "error", error: "数据库不可用" });',text:'数据库不可用：详细原因写日志，给平台的回答是 503 和一句简短的话。'}]}},python:{practice:{steps:['新建 app/cookies.py，按注释修改设置 Cookie 的几处和 main.py，补完健康检查的 TODO。','python -m pytest 确认第 17 关的测试仍然通过。','设置 COOKIE_SECURE=true 启动，用 curl -i 登录一次，看 Set-Cookie 里多了 Secure；不设置时没有。'],expect:'GET /api/health → 200 {"status":"ok"}\nset-cookie: session=…; HttpOnly; Max-Age=604800; Path=/; SameSite=lax; Secure'},code:'# app/cookies.py\nimport os\n\n# 线上用 HTTPS 时设置 COOKIE_SECURE=true，Cookie 只通过 HTTPS 发送\nSECURE = os.getenv("COOKIE_SECURE") == "true"\n\n\ndef set_session(response, token, max_age):\n    response.set_cookie("session", token, max_age=max_age, httponly=True, samesite="lax", secure=SECURE)\n\n\ndef clear_session(response):\n    response.delete_cookie("session", httponly=True, samesite="lax", secure=SECURE)\n\n\n# app/routers/auth.py、app/routers/oauth.py（模板渲染版本还有 main.py 的登录、退出）：\n# 原来 response.set_cookie("session", …) 的地方改成 set_session(response, token, auth.SESSION_TTL)，\n# response.delete_cookie("session", …) 改成 clear_session(response)；oauth 保存 state 的 Cookie 加上 secure=SECURE\n\n# main.py：最后启动服务的那一行改成（在 Docker 容器里要监听 0.0.0.0，外面才连得进来）\n    uvicorn.run(app, host=os.getenv("HOST", "127.0.0.1"), port=port)\n\n# main.py：顶部的导入改成\nimport sqlite3\n\nfrom app.database import init_db, query_one\n\n\n# main.py：健康检查改成\n@app.get("/api/health")\ndef health():\n    # TODO：用 query_one("SELECT 1") 问一下数据库；出 sqlite3.Error 时记日志，\n    #       返回 JSONResponse({"status": "error", "error": "数据库不可用"}, status_code=503)；正常时返回 {"status": "ok"}\n    return {"status": "ok"}',explain:[{at:'# app/cookies.py',to:'SECURE = os.getenv("COOKIE_SECURE") == "true"',text:'新建一个小文件，把会话 Cookie 的设置集中起来。SECURE 为 True 时，浏览器只会通过 HTTPS 发送这个 Cookie，就算有人诱导浏览器访问 http:// 地址，会话也不会以明文泄露。'},{at:'def set_session(response, token, max_age):',to:'secure=SECURE)',text:'设置会话 Cookie，属性和以前一样，多了 secure。'},{at:'def clear_session(response):',to:'response.delete_cookie(',text:'清除时的属性要和设置时一致。'},{at:'# main.py：最后启动服务的那一行改成',to:'uvicorn.run(app, host=os.getenv("HOST", "127.0.0.1"), port=port)',text:'127.0.0.1 只接受本机发来的请求。容器有自己的网络，外面的请求进不来，所以在 Docker 里要设置 HOST=0.0.0.0（接受所有网卡上的请求）。在自己电脑上不设置，还是只有本机能访问，更安全。'},{at:'# main.py：顶部的导入改成',to:'from app.database import init_db, query_one',text:'健康检查要用到 query_one 和 sqlite3 的异常类型。'},{at:'# main.py：健康检查改成',to:'def health():',text:'健康检查，要你改写。'},{at:'# TODO',to:'return {"status": "ok"}',text:'要你补全。'}],solution:{code:'# app/cookies.py\nimport os\n\n# 线上用 HTTPS 时设置 COOKIE_SECURE=true，Cookie 只通过 HTTPS 发送\nSECURE = os.getenv("COOKIE_SECURE") == "true"\n\n\ndef set_session(response, token, max_age):\n    response.set_cookie("session", token, max_age=max_age, httponly=True, samesite="lax", secure=SECURE)\n\n\ndef clear_session(response):\n    response.delete_cookie("session", httponly=True, samesite="lax", secure=SECURE)\n\n\n# app/routers/auth.py、app/routers/oauth.py（模板渲染版本还有 main.py 的登录、退出）：\n# 原来 response.set_cookie("session", …) 的地方改成 set_session(response, token, auth.SESSION_TTL)，\n# response.delete_cookie("session", …) 改成 clear_session(response)；oauth 保存 state 的 Cookie 加上 secure=SECURE\n\n# main.py：最后启动服务的那一行改成（在 Docker 容器里要监听 0.0.0.0，外面才连得进来）\n    uvicorn.run(app, host=os.getenv("HOST", "127.0.0.1"), port=port)\n\n# main.py：顶部的导入改成\nimport sqlite3\n\nfrom app.database import init_db, query_one\n\n\n# main.py：健康检查改成\n@app.get("/api/health")\ndef health():\n    try:\n        query_one("SELECT 1")\n    except sqlite3.Error:\n        log.exception("健康检查：数据库不可用")\n        return JSONResponse({"status": "error", "error": "数据库不可用"}, status_code=503)\n    return {"status": "ok"}',explain:[{at:'# app/cookies.py',to:'SECURE = os.getenv("COOKIE_SECURE") == "true"',text:'新建一个小文件，把会话 Cookie 的设置集中起来。SECURE 为 True 时，浏览器只会通过 HTTPS 发送这个 Cookie，就算有人诱导浏览器访问 http:// 地址，会话也不会以明文泄露。'},{at:'def set_session(response, token, max_age):',to:'secure=SECURE)',text:'设置会话 Cookie，属性和以前一样，多了 secure。'},{at:'def clear_session(response):',to:'response.delete_cookie(',text:'清除时的属性要和设置时一致。'},{at:'# main.py：最后启动服务的那一行改成',to:'uvicorn.run(app, host=os.getenv("HOST", "127.0.0.1"), port=port)',text:'127.0.0.1 只接受本机发来的请求。容器有自己的网络，外面的请求进不来，所以在 Docker 里要设置 HOST=0.0.0.0（接受所有网卡上的请求）。在自己电脑上不设置，还是只有本机能访问，更安全。'},{at:'# main.py：顶部的导入改成',to:'from app.database import init_db, query_one',text:'健康检查要用到 query_one 和 sqlite3 的异常类型。'},{at:'# main.py：健康检查改成',to:'def health():',text:'健康检查，要你改写。'},{at:'try:',to:'query_one("SELECT 1")',text:'SELECT 1 什么表都不查，只返回 1。能执行，说明数据库能用。'},{at:'except sqlite3.Error:',to:'return JSONResponse(',text:'数据库不可用：log.exception 把错误和调用栈写进日志，给平台的回答是 503 和一句简短的话。'},{at:'return {"status": "ok"}',text:'正常时 200。'}]}}}},
  {title:'任务二：Dockerfile 和自动测试',body:'写 Dockerfile 把项目打包成镜像，写 .dockerignore 排除不该打包的文件；再写 GitHub Actions 工作流，每次推送都自动跑测试和验收脚本。',variants:{go:{practice:{steps:['在项目根目录新建 Dockerfile 和 .dockerignore，补完 TODO。','新建 .github/workflows/ci.yml。把它和第 17 关的 checks 文件夹一起提交、推送到 GitHub，在仓库的 Actions 页面看它运行。','装了 Docker 的话：docker build -t zixishi . 构建镜像，docker run -p 8080:8080 zixishi 运行，打开 http://localhost:8080 试试。'],expect:'$ docker build -t zixishi .\n => [build 6/6] RUN CGO_ENABLED=0 go build -o /out/zixishi .\n => exporting to image\n$ docker images zixishi\nzixishi   latest   …   18MB'},code:'# Dockerfile\n# 第一阶段：在装了 Go 的镜像里编译\nFROM golang:1.26-alpine AS build\nWORKDIR /src\nCOPY go.mod go.sum ./\nRUN go mod download\nCOPY . .\n# TODO 1：用 RUN 编译出 /out/zixishi（加上 CGO_ENABLED=0，我们的 SQLite 驱动是纯 Go 写的）\n\n# 第二阶段：只把编译好的程序和它需要的文件放进一个很小的镜像\nFROM alpine:3.22\nWORKDIR /app\nCOPY --from=build /out/zixishi ./zixishi\nCOPY data/questions.json data/practice.json ./data/\nCOPY web ./web\n# 数据库放在单独的 /app/db 文件夹，运行时把它挂载到服务器的硬盘上，容器删了数据也还在\nRUN mkdir -p /app/db\nENV PORT=8080 DB_PATH=/app/db/zixishi.db\nEXPOSE 8080\n# TODO 2：用 CMD 写容器启动时执行的命令，运行 ./zixishi\n\n# .dockerignore：这些文件不复制进镜像\n.git\n*.exe\n*.db\nzixishi\n\n# .github/workflows/ci.yml\nname: CI\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-go@v5\n        with:\n          go-version-file: go.mod\n      - run: go vet ./...\n      - run: go test ./...\n      - run: go build -o zixishi .\n      - name: 启动服务，运行回归测试\n        env:\n          ADMIN_USERNAMES: admin_check\n          AI_BASE_URL: http://127.0.0.1:8090\n          AI_API_KEY: test-key\n          AI_MODEL: test-model\n          OAUTH_MOCK_URL: http://127.0.0.1:8091\n          GITHUB_CLIENT_ID: gh-id\n          GITHUB_CLIENT_SECRET: gh-secret\n          GOOGLE_CLIENT_ID: gg-id\n          GOOGLE_CLIENT_SECRET: gg-secret\n        run: |\n          ./zixishi &\n          for i in $(seq 60); do curl -sf http://localhost:8080/api/health && break; sleep 1; done\n          python3 checks/check_l17.py\n          python3 checks/check_l18.py',explain:[{at:'# Dockerfile',to:'FROM golang:1.26-alpine AS build',text:'第一阶段从官方的 Go 镜像开始（alpine 是一个很小的 Linux），AS build 给这个阶段起个名字。版本和 go.mod 里写的一致。'},{at:'WORKDIR /src',to:'RUN go mod download',text:'先只复制 go.mod 和 go.sum 并下载依赖。Docker 会缓存每一步的结果，只要依赖没变，下次构建就跳过这一步，快很多。'},{at:'COPY . .',text:'再复制全部源代码。'},{at:'# TODO 1',text:'编译，要你补全。'},{at:'# 第二阶段',to:'WORKDIR /app',text:'第二阶段从一个干净的 alpine 开始，最终的镜像只有十几 MB，里面没有 Go 编译器和源代码。'},{at:'COPY --from=build /out/zixishi ./zixishi',to:'COPY web ./web',text:'从第一阶段复制编译好的程序，再复制运行时要读的文件：题目和练习题的 JSON、网页文件夹（模板渲染版本是 web/templates，同样复制 web）。'},{at:'# 数据库放在单独的',to:'RUN mkdir -p /app/db',text:'容器被删除时，里面写的文件也没了。数据库放在单独的文件夹里，运行时用 -v 把服务器上的一个文件夹“挂载”到这里，数据就保存在服务器上。'},{at:'ENV PORT=8080',to:'EXPOSE 8080',text:'设置默认的环境变量；EXPOSE 说明程序监听 8080 端口。密钥这类配置不要写在这里，运行时再传。'},{at:'# TODO 2',text:'启动命令，要你补全。'},{at:'# .dockerignore',to:'zixishi',text:'.dockerignore 和 .gitignore 类似：COPY . . 时跳过这些文件。本地的数据库文件千万不能打包进镜像。'},{at:'# .github/workflows/ci.yml',to:'on: [push, pull_request]',text:'GitHub Actions 的工作流文件，放在仓库的 .github/workflows 文件夹里。on 说明什么时候运行：每次推送代码、每次有人提交合并请求。YAML 用缩进表示层级，缩进只能用空格。'},{at:'jobs:',to:'runs-on: ubuntu-latest',text:'一个叫 test 的任务，在 GitHub 提供的 Ubuntu 机器上运行。'},{at:'steps:',to:'- uses: actions/checkout@v4',text:'第一步把仓库的代码拉下来。uses 是使用别人写好的步骤，@v4 是版本。'},{at:'- uses: actions/setup-go@v5',to:'go-version-file: go.mod',text:'安装 go.mod 里写的 Go 版本。'},{at:'- run: go vet ./...',to:'- run: go build -o zixishi .',text:'检查代码、跑第 17 关的测试、编译出程序。'},{at:'- name: 启动服务，运行回归测试',to:'GOOGLE_CLIENT_SECRET: gg-secret',text:'设置和本地验收时一样的环境变量。全是测试用的假值，不是真密钥：真密钥要放在仓库的 Settings → Secrets 里，用 ${{ secrets.名字 }} 引用。'},{at:'run: |',to:'python3 checks/check_l18.py',text:'run: | 后面是多行命令。& 让服务在后台运行；for 循环每秒问一次健康检查，最多等 60 秒，通了就继续；然后运行第 17 关和第 18 关的验收脚本。任何一条命令失败，工作流就显示红叉。'}],solution:{code:'# Dockerfile\n# 第一阶段：在装了 Go 的镜像里编译\nFROM golang:1.26-alpine AS build\nWORKDIR /src\nCOPY go.mod go.sum ./\nRUN go mod download\nCOPY . .\nRUN CGO_ENABLED=0 go build -o /out/zixishi .\n\n# 第二阶段：只把编译好的程序和它需要的文件放进一个很小的镜像\nFROM alpine:3.22\nWORKDIR /app\nCOPY --from=build /out/zixishi ./zixishi\nCOPY data/questions.json data/practice.json ./data/\nCOPY web ./web\n# 数据库放在单独的 /app/db 文件夹，运行时把它挂载到服务器的硬盘上，容器删了数据也还在\nRUN mkdir -p /app/db\nENV PORT=8080 DB_PATH=/app/db/zixishi.db\nEXPOSE 8080\nCMD ["./zixishi"]\n\n# .dockerignore：这些文件不复制进镜像\n.git\n*.exe\n*.db\nzixishi\n\n# .github/workflows/ci.yml\nname: CI\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-go@v5\n        with:\n          go-version-file: go.mod\n      - run: go vet ./...\n      - run: go test ./...\n      - run: go build -o zixishi .\n      - name: 启动服务，运行回归测试\n        env:\n          ADMIN_USERNAMES: admin_check\n          AI_BASE_URL: http://127.0.0.1:8090\n          AI_API_KEY: test-key\n          AI_MODEL: test-model\n          OAUTH_MOCK_URL: http://127.0.0.1:8091\n          GITHUB_CLIENT_ID: gh-id\n          GITHUB_CLIENT_SECRET: gh-secret\n          GOOGLE_CLIENT_ID: gg-id\n          GOOGLE_CLIENT_SECRET: gg-secret\n        run: |\n          ./zixishi &\n          for i in $(seq 60); do curl -sf http://localhost:8080/api/health && break; sleep 1; done\n          python3 checks/check_l17.py\n          python3 checks/check_l18.py',explain:[{at:'# Dockerfile',to:'FROM golang:1.26-alpine AS build',text:'第一阶段从官方的 Go 镜像开始（alpine 是一个很小的 Linux），AS build 给这个阶段起个名字。版本和 go.mod 里写的一致。'},{at:'WORKDIR /src',to:'RUN go mod download',text:'先只复制 go.mod 和 go.sum 并下载依赖。Docker 会缓存每一步的结果，只要依赖没变，下次构建就跳过这一步，快很多。'},{at:'COPY . .',text:'再复制全部源代码。'},{at:'RUN CGO_ENABLED=0 go build -o /out/zixishi .',text:'编译。我们用的 SQLite 驱动是纯 Go 写的，CGO_ENABLED=0 编译出一个不依赖任何系统库的程序，放进 alpine 也能直接运行。'},{at:'# 第二阶段',to:'WORKDIR /app',text:'第二阶段从一个干净的 alpine 开始，最终的镜像只有十几 MB，里面没有 Go 编译器和源代码。'},{at:'COPY --from=build /out/zixishi ./zixishi',to:'COPY web ./web',text:'从第一阶段复制编译好的程序，再复制运行时要读的文件：题目和练习题的 JSON、网页文件夹（模板渲染版本是 web/templates，同样复制 web）。'},{at:'# 数据库放在单独的',to:'RUN mkdir -p /app/db',text:'容器被删除时，里面写的文件也没了。数据库放在单独的文件夹里，运行时用 -v 把服务器上的一个文件夹“挂载”到这里，数据就保存在服务器上。'},{at:'ENV PORT=8080',to:'EXPOSE 8080',text:'设置默认的环境变量；EXPOSE 说明程序监听 8080 端口。密钥这类配置不要写在这里，运行时再传。'},{at:'CMD ["./zixishi"]',text:'容器启动时运行我们的程序。写成 JSON 数组的形式，程序直接作为容器的主进程运行，能正确收到“停止”信号。'},{at:'# .dockerignore',to:'zixishi',text:'.dockerignore 和 .gitignore 类似：COPY . . 时跳过这些文件。本地的数据库文件千万不能打包进镜像。'},{at:'# .github/workflows/ci.yml',to:'on: [push, pull_request]',text:'GitHub Actions 的工作流文件，放在仓库的 .github/workflows 文件夹里。on 说明什么时候运行：每次推送代码、每次有人提交合并请求。YAML 用缩进表示层级，缩进只能用空格。'},{at:'jobs:',to:'runs-on: ubuntu-latest',text:'一个叫 test 的任务，在 GitHub 提供的 Ubuntu 机器上运行。'},{at:'steps:',to:'- uses: actions/checkout@v4',text:'第一步把仓库的代码拉下来。uses 是使用别人写好的步骤，@v4 是版本。'},{at:'- uses: actions/setup-go@v5',to:'go-version-file: go.mod',text:'安装 go.mod 里写的 Go 版本。'},{at:'- run: go vet ./...',to:'- run: go build -o zixishi .',text:'检查代码、跑第 17 关的测试、编译出程序。'},{at:'- name: 启动服务，运行回归测试',to:'GOOGLE_CLIENT_SECRET: gg-secret',text:'设置和本地验收时一样的环境变量。全是测试用的假值，不是真密钥：真密钥要放在仓库的 Settings → Secrets 里，用 ${{ secrets.名字 }} 引用。'},{at:'run: |',to:'python3 checks/check_l18.py',text:'run: | 后面是多行命令。& 让服务在后台运行；for 循环每秒问一次健康检查，最多等 60 秒，通了就继续；然后运行第 17 关和第 18 关的验收脚本。任何一条命令失败，工作流就显示红叉。'}]}},java:{practice:{steps:['在项目根目录新建 Dockerfile 和 .dockerignore，补完 TODO。','新建 .github/workflows/ci.yml。把它和 checks 文件夹（包括第 18 关的验收脚本）一起提交、推送到 GitHub，在仓库的 Actions 页面看它运行。','装了 Docker 的话：docker build -t zixishi . 构建镜像，docker run -p 8080:8080 zixishi 运行，打开 http://localhost:8080 试试。'],expect:'$ docker build -t zixishi .\n => [build 6/6] RUN ./mvnw -q -DskipTests package\n => exporting to image'},code:'# Dockerfile\n# 第一阶段：在装了 JDK 的镜像里用 Maven 打包\nFROM eclipse-temurin:21-jdk AS build\nWORKDIR /src\nCOPY .mvn .mvn\nCOPY mvnw pom.xml ./\nRUN chmod +x mvnw && ./mvnw -q dependency:go-offline\nCOPY src src\n# TODO 1：用 RUN 打包（./mvnw -q -DskipTests package，测试已经在 CI 里跑过了）\n\n# 第二阶段：只把打好的 jar 放进一个只有 Java 运行环境（JRE）的镜像\nFROM eclipse-temurin:21-jre\nWORKDIR /app\nCOPY --from=build /src/target/zixishi-0.0.1-SNAPSHOT.jar app.jar\nCOPY data/questions.json data/practice.json ./data/\n# 数据库放在单独的 /app/db 文件夹，运行时把它挂载到服务器的硬盘上，容器删了数据也还在\nRUN mkdir -p /app/db\nENV PORT=8080 DB_PATH=/app/db/zixishi.db\nEXPOSE 8080\n# TODO 2：用 CMD 写容器启动时执行的命令：java -jar app.jar\n\n# .dockerignore：这些文件不复制进镜像\ntarget\n.git\n*.db\n\n# .github/workflows/ci.yml\nname: CI\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: 21\n      - run: chmod +x mvnw && ./mvnw -B test\n      - run: ./mvnw -B -DskipTests package\n      - name: 启动服务，运行回归测试\n        env:\n          ADMIN_USERNAMES: admin_check\n          AI_BASE_URL: http://127.0.0.1:8090\n          AI_API_KEY: test-key\n          AI_MODEL: test-model\n          OAUTH_MOCK_URL: http://127.0.0.1:8091\n          GITHUB_CLIENT_ID: gh-id\n          GITHUB_CLIENT_SECRET: gh-secret\n          GOOGLE_CLIENT_ID: gg-id\n          GOOGLE_CLIENT_SECRET: gg-secret\n        run: |\n          java -jar target/zixishi-0.0.1-SNAPSHOT.jar &\n          for i in $(seq 60); do curl -sf http://localhost:8080/api/health && break; sleep 1; done\n          python3 checks/check_l17.py\n          python3 checks/check_l18.py',explain:[{at:'# Dockerfile',to:'FROM eclipse-temurin:21-jdk AS build',text:'第一阶段从 Eclipse Temurin 的 JDK 21 镜像开始（Temurin 是一个免费的 Java 发行版），AS build 给这个阶段起个名字。'},{at:'WORKDIR /src',to:'RUN chmod +x mvnw && ./mvnw -q dependency:go-offline',text:'先只复制 Maven 包装器和 pom.xml，下载全部依赖。Docker 会缓存每一步的结果，只要 pom.xml 没变，下次构建就跳过下载，快很多。chmod +x 给 mvnw 加上“可执行”权限（在 Windows 上提交的文件可能没有）。'},{at:'COPY src src',text:'再复制源代码。'},{at:'# TODO 1',text:'打包，要你补全。'},{at:'# 第二阶段',to:'WORKDIR /app',text:'第二阶段只要 JRE（运行 Java 程序的环境），不要编译器和 Maven，镜像小很多。'},{at:'COPY --from=build',to:'COPY data/questions.json data/practice.json ./data/',text:'从第一阶段复制打好的 jar（文件名和 pom.xml 里的 artifactId、version 对应），再复制运行时要读的题目和练习题。网页和模板已经打包在 jar 里了。'},{at:'# 数据库放在单独的',to:'RUN mkdir -p /app/db',text:'容器被删除时，里面写的文件也没了。数据库放在单独的文件夹里，运行时用 -v 把服务器上的一个文件夹“挂载”到这里，数据就保存在服务器上。'},{at:'ENV PORT=8080',to:'EXPOSE 8080',text:'设置默认的环境变量；EXPOSE 说明程序监听 8080 端口。密钥这类配置不要写在这里，运行时再传。'},{at:'# TODO 2',text:'启动命令，要你补全。'},{at:'# .dockerignore',to:'*.db',text:'COPY 时跳过这些文件：target 是本地编译的结果，镜像里会重新编译；本地的数据库文件千万不能打包进镜像。'},{at:'# .github/workflows/ci.yml',to:'on: [push, pull_request]',text:'GitHub Actions 的工作流文件，放在仓库的 .github/workflows 文件夹里。on 说明什么时候运行：每次推送代码、每次有人提交合并请求。YAML 用缩进表示层级，缩进只能用空格。'},{at:'jobs:',to:'runs-on: ubuntu-latest',text:'一个叫 test 的任务，在 GitHub 提供的 Ubuntu 机器上运行。'},{at:'steps:',to:'- uses: actions/checkout@v4',text:'第一步把仓库的代码拉下来。uses 是使用别人写好的步骤，@v4 是版本。'},{at:'- uses: actions/setup-java@v4',to:'java-version: 21',text:'安装 Temurin 的 Java 21。'},{at:'- run: chmod +x mvnw && ./mvnw -B test',to:'- run: ./mvnw -B -DskipTests package',text:'跑第 17 关的测试，再打包。-B 是“批处理模式”，日志更适合在 CI 里看。'},{at:'- name: 启动服务，运行回归测试',to:'GOOGLE_CLIENT_SECRET: gg-secret',text:'设置和本地验收时一样的环境变量。全是测试用的假值，不是真密钥：真密钥要放在仓库的 Settings → Secrets 里，用 ${{ secrets.名字 }} 引用。'},{at:'run: |',to:'python3 checks/check_l18.py',text:'run: | 后面是多行命令。& 让服务在后台运行；for 循环每秒问一次健康检查，最多等 60 秒，通了就继续；然后运行第 17 关和第 18 关的验收脚本。任何一条命令失败，工作流就显示红叉。'}],solution:{code:'# Dockerfile\n# 第一阶段：在装了 JDK 的镜像里用 Maven 打包\nFROM eclipse-temurin:21-jdk AS build\nWORKDIR /src\nCOPY .mvn .mvn\nCOPY mvnw pom.xml ./\nRUN chmod +x mvnw && ./mvnw -q dependency:go-offline\nCOPY src src\nRUN ./mvnw -q -DskipTests package\n\n# 第二阶段：只把打好的 jar 放进一个只有 Java 运行环境（JRE）的镜像\nFROM eclipse-temurin:21-jre\nWORKDIR /app\nCOPY --from=build /src/target/zixishi-0.0.1-SNAPSHOT.jar app.jar\nCOPY data/questions.json data/practice.json ./data/\n# 数据库放在单独的 /app/db 文件夹，运行时把它挂载到服务器的硬盘上，容器删了数据也还在\nRUN mkdir -p /app/db\nENV PORT=8080 DB_PATH=/app/db/zixishi.db\nEXPOSE 8080\nCMD ["java", "-jar", "app.jar"]\n\n# .dockerignore：这些文件不复制进镜像\ntarget\n.git\n*.db\n\n# .github/workflows/ci.yml\nname: CI\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: 21\n      - run: chmod +x mvnw && ./mvnw -B test\n      - run: ./mvnw -B -DskipTests package\n      - name: 启动服务，运行回归测试\n        env:\n          ADMIN_USERNAMES: admin_check\n          AI_BASE_URL: http://127.0.0.1:8090\n          AI_API_KEY: test-key\n          AI_MODEL: test-model\n          OAUTH_MOCK_URL: http://127.0.0.1:8091\n          GITHUB_CLIENT_ID: gh-id\n          GITHUB_CLIENT_SECRET: gh-secret\n          GOOGLE_CLIENT_ID: gg-id\n          GOOGLE_CLIENT_SECRET: gg-secret\n        run: |\n          java -jar target/zixishi-0.0.1-SNAPSHOT.jar &\n          for i in $(seq 60); do curl -sf http://localhost:8080/api/health && break; sleep 1; done\n          python3 checks/check_l17.py\n          python3 checks/check_l18.py',explain:[{at:'# Dockerfile',to:'FROM eclipse-temurin:21-jdk AS build',text:'第一阶段从 Eclipse Temurin 的 JDK 21 镜像开始（Temurin 是一个免费的 Java 发行版），AS build 给这个阶段起个名字。'},{at:'WORKDIR /src',to:'RUN chmod +x mvnw && ./mvnw -q dependency:go-offline',text:'先只复制 Maven 包装器和 pom.xml，下载全部依赖。Docker 会缓存每一步的结果，只要 pom.xml 没变，下次构建就跳过下载，快很多。chmod +x 给 mvnw 加上“可执行”权限（在 Windows 上提交的文件可能没有）。'},{at:'COPY src src',text:'再复制源代码。'},{at:'RUN ./mvnw -q -DskipTests package',text:'打包出 jar。-DskipTests 跳过测试：测试已经在 CI 里跑过了。'},{at:'# 第二阶段',to:'WORKDIR /app',text:'第二阶段只要 JRE（运行 Java 程序的环境），不要编译器和 Maven，镜像小很多。'},{at:'COPY --from=build',to:'COPY data/questions.json data/practice.json ./data/',text:'从第一阶段复制打好的 jar（文件名和 pom.xml 里的 artifactId、version 对应），再复制运行时要读的题目和练习题。网页和模板已经打包在 jar 里了。'},{at:'# 数据库放在单独的',to:'RUN mkdir -p /app/db',text:'容器被删除时，里面写的文件也没了。数据库放在单独的文件夹里，运行时用 -v 把服务器上的一个文件夹“挂载”到这里，数据就保存在服务器上。'},{at:'ENV PORT=8080',to:'EXPOSE 8080',text:'设置默认的环境变量；EXPOSE 说明程序监听 8080 端口。密钥这类配置不要写在这里，运行时再传。'},{at:'CMD ["java", "-jar", "app.jar"]',text:'容器启动时运行 jar。写成 JSON 数组的形式，程序直接作为容器的主进程运行，能正确收到“停止”信号。'},{at:'# .dockerignore',to:'*.db',text:'COPY 时跳过这些文件：target 是本地编译的结果，镜像里会重新编译；本地的数据库文件千万不能打包进镜像。'},{at:'# .github/workflows/ci.yml',to:'on: [push, pull_request]',text:'GitHub Actions 的工作流文件，放在仓库的 .github/workflows 文件夹里。on 说明什么时候运行：每次推送代码、每次有人提交合并请求。YAML 用缩进表示层级，缩进只能用空格。'},{at:'jobs:',to:'runs-on: ubuntu-latest',text:'一个叫 test 的任务，在 GitHub 提供的 Ubuntu 机器上运行。'},{at:'steps:',to:'- uses: actions/checkout@v4',text:'第一步把仓库的代码拉下来。uses 是使用别人写好的步骤，@v4 是版本。'},{at:'- uses: actions/setup-java@v4',to:'java-version: 21',text:'安装 Temurin 的 Java 21。'},{at:'- run: chmod +x mvnw && ./mvnw -B test',to:'- run: ./mvnw -B -DskipTests package',text:'跑第 17 关的测试，再打包。-B 是“批处理模式”，日志更适合在 CI 里看。'},{at:'- name: 启动服务，运行回归测试',to:'GOOGLE_CLIENT_SECRET: gg-secret',text:'设置和本地验收时一样的环境变量。全是测试用的假值，不是真密钥：真密钥要放在仓库的 Settings → Secrets 里，用 ${{ secrets.名字 }} 引用。'},{at:'run: |',to:'python3 checks/check_l18.py',text:'run: | 后面是多行命令。& 让服务在后台运行；for 循环每秒问一次健康检查，最多等 60 秒，通了就继续；然后运行第 17 关和第 18 关的验收脚本。任何一条命令失败，工作流就显示红叉。'}]}},node:{practice:{steps:['在项目根目录新建 Dockerfile 和 .dockerignore，补完 TODO。','新建 .github/workflows/ci.yml。把它和 checks 文件夹（包括第 18 关的验收脚本）一起提交、推送到 GitHub，在仓库的 Actions 页面看它运行。','装了 Docker 的话：docker build -t zixishi . 构建镜像，docker run -p 8080:8080 zixishi 运行，打开 http://localhost:8080 试试。'],expect:'$ docker build -t zixishi .\n => [3/5] RUN npm ci --omit=dev\n => exporting to image'},code:'# Dockerfile\nFROM node:22-slim\nWORKDIR /app\nCOPY package.json package-lock.json ./\n# TODO 1：用 RUN 按 package-lock.json 安装依赖（npm ci），不装开发用的依赖（--omit=dev）\nCOPY . .\n# 数据库放在单独的 /app/db 文件夹，运行时把它挂载到服务器的硬盘上，容器删了数据也还在\nRUN mkdir -p /app/db\nENV NODE_ENV=production PORT=8080 DB_PATH=/app/db/zixishi.db\nEXPOSE 8080\n# TODO 2：用 CMD 写容器启动时执行的命令：node app.js\n\n# .dockerignore：这些文件不复制进镜像\nnode_modules\n.git\n*.db\n\n# .github/workflows/ci.yml\nname: CI\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      - run: npm ci\n      - run: node --test\n      - name: 启动服务，运行回归测试\n        env:\n          ADMIN_USERNAMES: admin_check\n          AI_BASE_URL: http://127.0.0.1:8090\n          AI_API_KEY: test-key\n          AI_MODEL: test-model\n          OAUTH_MOCK_URL: http://127.0.0.1:8091\n          GITHUB_CLIENT_ID: gh-id\n          GITHUB_CLIENT_SECRET: gh-secret\n          GOOGLE_CLIENT_ID: gg-id\n          GOOGLE_CLIENT_SECRET: gg-secret\n        run: |\n          node app.js &\n          for i in $(seq 60); do curl -sf http://localhost:8080/api/health && break; sleep 1; done\n          python3 checks/check_l17.py\n          python3 checks/check_l18.py',explain:[{at:'# Dockerfile',to:'FROM node:22-slim',text:'从官方的 Node.js 22 镜像开始。slim 是精简版的 Debian Linux，better-sqlite3 有现成编译好的版本，不用在镜像里编译。'},{at:'WORKDIR /app',to:'COPY package.json package-lock.json ./',text:'先只复制依赖清单。Docker 会缓存每一步的结果，只要依赖没变，下次构建就跳过安装这一步，快很多。'},{at:'# TODO 1',text:'安装依赖，要你补全。'},{at:'COPY . .',text:'再复制全部代码（.dockerignore 里的除外）。'},{at:'# 数据库放在单独的',to:'RUN mkdir -p /app/db',text:'容器被删除时，里面写的文件也没了。数据库放在单独的文件夹里，运行时用 -v 把服务器上的一个文件夹“挂载”到这里，数据就保存在服务器上。'},{at:'ENV NODE_ENV=production',to:'EXPOSE 8080',text:'设置默认的环境变量。NODE_ENV=production 告诉 Express 等库“这是生产环境”，会关掉一些调试功能。密钥这类配置不要写在这里，运行时再传。EXPOSE 说明程序监听 8080 端口。'},{at:'# TODO 2',text:'启动命令，要你补全。'},{at:'# .dockerignore',to:'*.db',text:'COPY . . 时跳过这些文件：node_modules 在镜像里重新安装（你电脑上的可能是 Windows 版本），本地的数据库文件千万不能打包进镜像。'},{at:'# .github/workflows/ci.yml',to:'on: [push, pull_request]',text:'GitHub Actions 的工作流文件，放在仓库的 .github/workflows 文件夹里。on 说明什么时候运行：每次推送代码、每次有人提交合并请求。YAML 用缩进表示层级，缩进只能用空格。'},{at:'jobs:',to:'runs-on: ubuntu-latest',text:'一个叫 test 的任务，在 GitHub 提供的 Ubuntu 机器上运行。'},{at:'steps:',to:'- uses: actions/checkout@v4',text:'第一步把仓库的代码拉下来。uses 是使用别人写好的步骤，@v4 是版本。'},{at:'- uses: actions/setup-node@v4',to:'node-version: 22',text:'安装 Node.js 22。'},{at:'- run: npm ci',to:'- run: node --test',text:'安装依赖，跑第 17 关的测试。'},{at:'- name: 启动服务，运行回归测试',to:'GOOGLE_CLIENT_SECRET: gg-secret',text:'设置和本地验收时一样的环境变量。全是测试用的假值，不是真密钥：真密钥要放在仓库的 Settings → Secrets 里，用 ${{ secrets.名字 }} 引用。'},{at:'run: |',to:'python3 checks/check_l18.py',text:'run: | 后面是多行命令。& 让服务在后台运行；for 循环每秒问一次健康检查，最多等 60 秒，通了就继续；然后运行第 17 关和第 18 关的验收脚本。任何一条命令失败，工作流就显示红叉。'}],solution:{code:'# Dockerfile\nFROM node:22-slim\nWORKDIR /app\nCOPY package.json package-lock.json ./\nRUN npm ci --omit=dev\nCOPY . .\n# 数据库放在单独的 /app/db 文件夹，运行时把它挂载到服务器的硬盘上，容器删了数据也还在\nRUN mkdir -p /app/db\nENV NODE_ENV=production PORT=8080 DB_PATH=/app/db/zixishi.db\nEXPOSE 8080\nCMD ["node", "app.js"]\n\n# .dockerignore：这些文件不复制进镜像\nnode_modules\n.git\n*.db\n\n# .github/workflows/ci.yml\nname: CI\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      - run: npm ci\n      - run: node --test\n      - name: 启动服务，运行回归测试\n        env:\n          ADMIN_USERNAMES: admin_check\n          AI_BASE_URL: http://127.0.0.1:8090\n          AI_API_KEY: test-key\n          AI_MODEL: test-model\n          OAUTH_MOCK_URL: http://127.0.0.1:8091\n          GITHUB_CLIENT_ID: gh-id\n          GITHUB_CLIENT_SECRET: gh-secret\n          GOOGLE_CLIENT_ID: gg-id\n          GOOGLE_CLIENT_SECRET: gg-secret\n        run: |\n          node app.js &\n          for i in $(seq 60); do curl -sf http://localhost:8080/api/health && break; sleep 1; done\n          python3 checks/check_l17.py\n          python3 checks/check_l18.py',explain:[{at:'# Dockerfile',to:'FROM node:22-slim',text:'从官方的 Node.js 22 镜像开始。slim 是精简版的 Debian Linux，better-sqlite3 有现成编译好的版本，不用在镜像里编译。'},{at:'WORKDIR /app',to:'COPY package.json package-lock.json ./',text:'先只复制依赖清单。Docker 会缓存每一步的结果，只要依赖没变，下次构建就跳过安装这一步，快很多。'},{at:'RUN npm ci --omit=dev',text:'npm ci 严格按 package-lock.json 安装，每次装出来的版本完全一样；--omit=dev 不装只在开发时用的包。'},{at:'COPY . .',text:'再复制全部代码（.dockerignore 里的除外）。'},{at:'# 数据库放在单独的',to:'RUN mkdir -p /app/db',text:'容器被删除时，里面写的文件也没了。数据库放在单独的文件夹里，运行时用 -v 把服务器上的一个文件夹“挂载”到这里，数据就保存在服务器上。'},{at:'ENV NODE_ENV=production',to:'EXPOSE 8080',text:'设置默认的环境变量。NODE_ENV=production 告诉 Express 等库“这是生产环境”，会关掉一些调试功能。密钥这类配置不要写在这里，运行时再传。EXPOSE 说明程序监听 8080 端口。'},{at:'CMD ["node", "app.js"]',text:'容器启动时运行我们的程序。写成 JSON 数组的形式，程序直接作为容器的主进程运行，能正确收到“停止”信号。'},{at:'# .dockerignore',to:'*.db',text:'COPY . . 时跳过这些文件：node_modules 在镜像里重新安装（你电脑上的可能是 Windows 版本），本地的数据库文件千万不能打包进镜像。'},{at:'# .github/workflows/ci.yml',to:'on: [push, pull_request]',text:'GitHub Actions 的工作流文件，放在仓库的 .github/workflows 文件夹里。on 说明什么时候运行：每次推送代码、每次有人提交合并请求。YAML 用缩进表示层级，缩进只能用空格。'},{at:'jobs:',to:'runs-on: ubuntu-latest',text:'一个叫 test 的任务，在 GitHub 提供的 Ubuntu 机器上运行。'},{at:'steps:',to:'- uses: actions/checkout@v4',text:'第一步把仓库的代码拉下来。uses 是使用别人写好的步骤，@v4 是版本。'},{at:'- uses: actions/setup-node@v4',to:'node-version: 22',text:'安装 Node.js 22。'},{at:'- run: npm ci',to:'- run: node --test',text:'安装依赖，跑第 17 关的测试。'},{at:'- name: 启动服务，运行回归测试',to:'GOOGLE_CLIENT_SECRET: gg-secret',text:'设置和本地验收时一样的环境变量。全是测试用的假值，不是真密钥：真密钥要放在仓库的 Settings → Secrets 里，用 ${{ secrets.名字 }} 引用。'},{at:'run: |',to:'python3 checks/check_l18.py',text:'run: | 后面是多行命令。& 让服务在后台运行；for 循环每秒问一次健康检查，最多等 60 秒，通了就继续；然后运行第 17 关和第 18 关的验收脚本。任何一条命令失败，工作流就显示红叉。'}]}},python:{practice:{steps:['在项目根目录新建 Dockerfile 和 .dockerignore，补完 TODO。','新建 .github/workflows/ci.yml。把它和 checks 文件夹（包括第 18 关的验收脚本）一起提交、推送到 GitHub，在仓库的 Actions 页面看它运行。','装了 Docker 的话：docker build -t zixishi . 构建镜像，docker run -p 8080:8080 zixishi 运行，打开 http://localhost:8080 试试。'],expect:'$ docker build -t zixishi .\n => [3/5] RUN pip install --no-cache-dir -r requirements.txt\n => exporting to image'},code:'# Dockerfile\nFROM python:3.13-slim\nWORKDIR /app\nCOPY requirements.txt ./\n# TODO 1：用 RUN 安装 requirements.txt 里的依赖（加上 --no-cache-dir，镜像小一些）\nCOPY . .\n# 数据库放在单独的 /app/db 文件夹，运行时把它挂载到服务器的硬盘上，容器删了数据也还在\nRUN mkdir -p /app/db\nENV HOST=0.0.0.0 PORT=8080 DB_PATH=/app/db/zixishi.db\nEXPOSE 8080\n# TODO 2：用 CMD 写容器启动时执行的命令：python main.py\n\n# .dockerignore：这些文件不复制进镜像\n.venv\n__pycache__\n.git\n*.db\n\n# .github/workflows/ci.yml\nname: CI\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.13"\n      - run: pip install -r requirements.txt pytest\n      - run: python -m pytest\n      - name: 启动服务，运行回归测试\n        env:\n          ADMIN_USERNAMES: admin_check\n          AI_BASE_URL: http://127.0.0.1:8090\n          AI_API_KEY: test-key\n          AI_MODEL: test-model\n          OAUTH_MOCK_URL: http://127.0.0.1:8091\n          GITHUB_CLIENT_ID: gh-id\n          GITHUB_CLIENT_SECRET: gh-secret\n          GOOGLE_CLIENT_ID: gg-id\n          GOOGLE_CLIENT_SECRET: gg-secret\n        run: |\n          python main.py &\n          for i in $(seq 60); do curl -sf http://localhost:8080/api/health && break; sleep 1; done\n          python3 checks/check_l17.py\n          python3 checks/check_l18.py',explain:[{at:'# Dockerfile',to:'FROM python:3.13-slim',text:'从官方的 Python 3.13 镜像开始，slim 是精简版的 Debian Linux。'},{at:'WORKDIR /app',to:'COPY requirements.txt ./',text:'先只复制依赖清单。Docker 会缓存每一步的结果，只要依赖没变，下次构建就跳过安装这一步，快很多。'},{at:'# TODO 1',text:'安装依赖，要你补全。'},{at:'COPY . .',text:'再复制全部代码（.dockerignore 里的除外）。'},{at:'# 数据库放在单独的',to:'RUN mkdir -p /app/db',text:'容器被删除时，里面写的文件也没了。数据库放在单独的文件夹里，运行时用 -v 把服务器上的一个文件夹“挂载”到这里，数据就保存在服务器上。'},{at:'ENV HOST=0.0.0.0',to:'EXPOSE 8080',text:'设置默认的环境变量：HOST=0.0.0.0 让服务接受容器外面来的请求（任务一加的）。密钥这类配置不要写在这里，运行时再传。EXPOSE 说明程序监听 8080 端口。'},{at:'# TODO 2',text:'启动命令，要你补全。'},{at:'# .dockerignore',to:'*.db',text:'COPY . . 时跳过这些文件：虚拟环境在镜像里不需要（依赖已经装在镜像的 Python 里），本地的数据库文件千万不能打包进镜像。'},{at:'# .github/workflows/ci.yml',to:'on: [push, pull_request]',text:'GitHub Actions 的工作流文件，放在仓库的 .github/workflows 文件夹里。on 说明什么时候运行：每次推送代码、每次有人提交合并请求。YAML 用缩进表示层级，缩进只能用空格。'},{at:'jobs:',to:'runs-on: ubuntu-latest',text:'一个叫 test 的任务，在 GitHub 提供的 Ubuntu 机器上运行。'},{at:'steps:',to:'- uses: actions/checkout@v4',text:'第一步把仓库的代码拉下来。uses 是使用别人写好的步骤，@v4 是版本。'},{at:'- uses: actions/setup-python@v5',to:'python-version: "3.13"',text:'安装 Python 3.13。版本号加引号，否则 YAML 可能把 3.10 读成数字 3.1。'},{at:'- run: pip install -r requirements.txt pytest',to:'- run: python -m pytest',text:'安装依赖和 pytest，跑第 17 关的测试。'},{at:'- name: 启动服务，运行回归测试',to:'GOOGLE_CLIENT_SECRET: gg-secret',text:'设置和本地验收时一样的环境变量。全是测试用的假值，不是真密钥：真密钥要放在仓库的 Settings → Secrets 里，用 ${{ secrets.名字 }} 引用。'},{at:'run: |',to:'python3 checks/check_l18.py',text:'run: | 后面是多行命令。& 让服务在后台运行；for 循环每秒问一次健康检查，最多等 60 秒，通了就继续；然后运行第 17 关和第 18 关的验收脚本。任何一条命令失败，工作流就显示红叉。'}],solution:{code:'# Dockerfile\nFROM python:3.13-slim\nWORKDIR /app\nCOPY requirements.txt ./\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY . .\n# 数据库放在单独的 /app/db 文件夹，运行时把它挂载到服务器的硬盘上，容器删了数据也还在\nRUN mkdir -p /app/db\nENV HOST=0.0.0.0 PORT=8080 DB_PATH=/app/db/zixishi.db\nEXPOSE 8080\nCMD ["python", "main.py"]\n\n# .dockerignore：这些文件不复制进镜像\n.venv\n__pycache__\n.git\n*.db\n\n# .github/workflows/ci.yml\nname: CI\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.13"\n      - run: pip install -r requirements.txt pytest\n      - run: python -m pytest\n      - name: 启动服务，运行回归测试\n        env:\n          ADMIN_USERNAMES: admin_check\n          AI_BASE_URL: http://127.0.0.1:8090\n          AI_API_KEY: test-key\n          AI_MODEL: test-model\n          OAUTH_MOCK_URL: http://127.0.0.1:8091\n          GITHUB_CLIENT_ID: gh-id\n          GITHUB_CLIENT_SECRET: gh-secret\n          GOOGLE_CLIENT_ID: gg-id\n          GOOGLE_CLIENT_SECRET: gg-secret\n        run: |\n          python main.py &\n          for i in $(seq 60); do curl -sf http://localhost:8080/api/health && break; sleep 1; done\n          python3 checks/check_l17.py\n          python3 checks/check_l18.py',explain:[{at:'# Dockerfile',to:'FROM python:3.13-slim',text:'从官方的 Python 3.13 镜像开始，slim 是精简版的 Debian Linux。'},{at:'WORKDIR /app',to:'COPY requirements.txt ./',text:'先只复制依赖清单。Docker 会缓存每一步的结果，只要依赖没变，下次构建就跳过安装这一步，快很多。'},{at:'RUN pip install --no-cache-dir -r requirements.txt',text:'安装依赖；--no-cache-dir 不保留下载的安装包，镜像小一些。'},{at:'COPY . .',text:'再复制全部代码（.dockerignore 里的除外）。'},{at:'# 数据库放在单独的',to:'RUN mkdir -p /app/db',text:'容器被删除时，里面写的文件也没了。数据库放在单独的文件夹里，运行时用 -v 把服务器上的一个文件夹“挂载”到这里，数据就保存在服务器上。'},{at:'ENV HOST=0.0.0.0',to:'EXPOSE 8080',text:'设置默认的环境变量：HOST=0.0.0.0 让服务接受容器外面来的请求（任务一加的）。密钥这类配置不要写在这里，运行时再传。EXPOSE 说明程序监听 8080 端口。'},{at:'CMD ["python", "main.py"]',text:'容器启动时运行我们的程序。写成 JSON 数组的形式，程序直接作为容器的主进程运行，能正确收到“停止”信号。'},{at:'# .dockerignore',to:'*.db',text:'COPY . . 时跳过这些文件：虚拟环境在镜像里不需要（依赖已经装在镜像的 Python 里），本地的数据库文件千万不能打包进镜像。'},{at:'# .github/workflows/ci.yml',to:'on: [push, pull_request]',text:'GitHub Actions 的工作流文件，放在仓库的 .github/workflows 文件夹里。on 说明什么时候运行：每次推送代码、每次有人提交合并请求。YAML 用缩进表示层级，缩进只能用空格。'},{at:'jobs:',to:'runs-on: ubuntu-latest',text:'一个叫 test 的任务，在 GitHub 提供的 Ubuntu 机器上运行。'},{at:'steps:',to:'- uses: actions/checkout@v4',text:'第一步把仓库的代码拉下来。uses 是使用别人写好的步骤，@v4 是版本。'},{at:'- uses: actions/setup-python@v5',to:'python-version: "3.13"',text:'安装 Python 3.13。版本号加引号，否则 YAML 可能把 3.10 读成数字 3.1。'},{at:'- run: pip install -r requirements.txt pytest',to:'- run: python -m pytest',text:'安装依赖和 pytest，跑第 17 关的测试。'},{at:'- name: 启动服务，运行回归测试',to:'GOOGLE_CLIENT_SECRET: gg-secret',text:'设置和本地验收时一样的环境变量。全是测试用的假值，不是真密钥：真密钥要放在仓库的 Settings → Secrets 里，用 ${{ secrets.名字 }} 引用。'},{at:'run: |',to:'python3 checks/check_l18.py',text:'run: | 后面是多行命令。& 让服务在后台运行；for 循环每秒问一次健康检查，最多等 60 秒，通了就继续；然后运行第 17 关和第 18 关的验收脚本。任何一条命令失败，工作流就显示红叉。'}]}}}},
  {title:'任务三：部署到服务器',body:'选一台云服务器（比如阿里云、腾讯云的轻量应用服务器，最低配置就够），买一个域名并把它解析到服务器的公网 IP。下面的命令在服务器上执行（Ubuntu 系统，先按 Docker 官网的说明装好 Docker 和 Caddy）。\n密钥写在服务器上的一个环境变量文件里，只有自己能读，绝不提交到 Git。第三方登录的回调地址要换成 https://你的域名/auth/github/callback，在 GitHub 的应用设置里同样改掉。\nCaddy 是一个 Web 服务器，它会自动申请和续期免费的 HTTPS 证书，再把请求转给我们的程序。',code:`# 1. 取代码、构建镜像
git clone https://github.com/你的用户名/zixishi.git
cd zixishi
docker build -t zixishi .

# 2. 密钥写进 /srv/zixishi.env（每行一个 名字=值），只有自己能读
sudo mkdir -p /srv/zixishi
sudo nano /srv/zixishi.env
sudo chmod 600 /srv/zixishi.env

# 3. 运行容器：只在本机的 8080 端口上开放，数据库放在 /srv/zixishi
docker run -d --name zixishi --restart unless-stopped \\
  -p 127.0.0.1:8080:8080 \\
  -v /srv/zixishi:/app/db \\
  -e COOKIE_SECURE=true \\
  --env-file /srv/zixishi.env zixishi

# 4. /etc/caddy/Caddyfile：把你的域名转给 8080，HTTPS 证书自动申请
zixishi.example.com {
    reverse_proxy 127.0.0.1:8080
}
# 改完执行 sudo systemctl reload caddy

# 5. 以后更新：拉代码、重新构建、换掉旧容器（数据在 /srv/zixishi，不会丢）
git pull && docker build -t zixishi . && docker rm -f zixishi
# 然后再执行一遍第 3 步

# 6. 备份数据库（可以写进 crontab 每天执行）
sqlite3 /srv/zixishi/zixishi.db ".backup /srv/backup-$(date +%F).db"`,explain:[{at:'# 1. 取代码、构建镜像',to:'docker build -t zixishi .',text:'在服务器上把仓库拉下来，用任务二的 Dockerfile 构建镜像，-t 给镜像起名字 zixishi。'},{at:'# 2. 密钥写进',to:'sudo chmod 600 /srv/zixishi.env',text:'/srv/zixishi 放数据库。环境变量文件里写 AI_API_KEY、GITHUB_CLIENT_SECRET、ADMIN_USERNAMES 这些。chmod 600 让只有文件的主人能读写。'},{at:'# 3. 运行容器',to:'--restart unless-stopped',text:'-d 在后台运行；--restart unless-stopped 让容器出错退出、服务器重启后自动再启动；行末的 \\ 表示命令还没完，下一行接着写。'},{at:'-p 127.0.0.1:8080:8080',text:'把容器的 8080 端口映射到服务器的 8080，但只对本机开放：外面只能通过 Caddy 的 HTTPS 访问，不能绕过它直接用 http 访问 8080。'},{at:'-v /srv/zixishi:/app/db',text:'把服务器上的 /srv/zixishi 挂载到容器的 /app/db：数据库写在服务器的硬盘上，换掉容器数据也还在。'},{at:'-e COOKIE_SECURE=true',to:'--env-file /srv/zixishi.env',text:'线上是 HTTPS，打开 Cookie 的 Secure；其他配置从环境变量文件读取；最后的 zixishi 是要运行的镜像名。'},{at:'# 4. /etc/caddy/Caddyfile',to:'# 改完执行 sudo systemctl reload caddy',text:'Caddy 的配置文件：访问 zixishi.example.com（换成你的域名）的请求都转给本机的 8080。Caddy 发现这是一个域名，会自动去申请 HTTPS 证书。'},{at:'# 5. 以后更新',to:'# 然后再执行一遍第 3 步',text:'更新流程：拉最新代码、重新构建镜像、删掉旧容器、用新镜像再运行。数据库在挂载的文件夹里，不受影响。'},{at:'# 6. 备份数据库',to:'sqlite3 /srv/zixishi/zixishi.db',text:'SQLite 的 .backup 命令在服务运行时也能安全地复制出一份完整的数据库。备份最好再复制到另一台机器或者对象存储上。'}]},
  {title:'验收：检查线上的服务',body:'最后一个验收脚本从外面检查一个部署好的服务：健康检查、首页、错误处理、有没有泄露不该公开的文件、会话 Cookie 的安全属性。\n先在本地运行一次（python checks/check_l18.py），全部通过后再部署；部署好以后，把线上地址传给它再运行一次：python checks/check_l18.py https://你的域名。用 HTTPS 地址运行时，会多检查一项：会话 Cookie 带 Secure。',practice:{steps:['在本地启动后端，把下面的脚本保存为 checks/check_l18.py，运行 python checks/check_l18.py，直到全部 ✓。','按上一张卡片部署到服务器，运行 python checks/check_l18.py https://你的域名，直到全部 ✓（8 项）。','全部通过后提交：git add . 然后 git commit -m "第 18 关：部署上线"，推送到 GitHub，看 Actions 页面变成绿色的对勾。'],expect:'✓ 健康检查返回 200 {"status": "ok"}，5 秒内响应\n✓ 响应带上了 X-Request-Id，方便对照日志\n✓ 首页能打开\n✓ 不存在的接口返回 404 和 JSON 错误\n✓ 格式错误的请求返回 400，不是 500\n✓ 下载不到数据库文件、.env、.git 这些不该公开的文件\n✓ 登录成功，会话 Cookie 带 HttpOnly 和 SameSite\n✓ 用 HTTPS 访问时，会话 Cookie 带 Secure\n\n通过 8 / 8'},code:`import json
import random
import sys
import time
import urllib.error
import urllib.request

BASE = (sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080").rstrip("/")
HTTPS = BASE.startswith("https://")
passed = 0


def check(name, ok):
    global passed
    print(("✓ " if ok else "✗ ") + name)
    passed += bool(ok)


def request(method, path, data=None):
    """发一个请求，返回 (状态码, 响应头, 正文字节)；不自动跟随重定向以外的任何处理"""
    req = urllib.request.Request(BASE + path, data=data, method=method, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            return r.status, r.headers, r.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()
    except OSError as e:
        sys.exit(f"连不上 {BASE}，服务启动了吗？地址对吗？（{e}）")


def as_json(body):
    try:
        return json.loads(body.decode("utf-8"))
    except ValueError:
        return None


start = time.perf_counter()
status, headers, body = request("GET", "/api/health")
check("健康检查返回 200 {\\"status\\": \\"ok\\"}，5 秒内响应",
      status == 200 and as_json(body) == {"status": "ok"} and time.perf_counter() - start < 5)
check("响应带上了 X-Request-Id，方便对照日志", bool(headers.get("X-Request-Id")))

status, headers, body = request("GET", "/")
check("首页能打开", status == 200 and "text/html" in headers.get("Content-Type", ""))

status, headers, body = request("GET", "/api/no-such-thing")
check("不存在的接口返回 404 和 JSON 错误", status == 404 and isinstance(as_json(body), dict))

status, _, body = request("POST", "/api/login", b"{not json")
check("格式错误的请求返回 400，不是 500", status == 400)

leaked = []
for path in ["/data/zixishi.db", "/zixishi.db", "/db/zixishi.db", "/.env", "/.git/config"]:
    status, _, body = request("GET", path)
    if status == 200 and (body.startswith(b"SQLite format 3") or b"[core]" in body or b"_KEY=" in body):
        leaked.append(path)
check("下载不到数据库文件、.env、.git 这些不该公开的文件" + (f"（泄露了 {leaked}）" if leaked else ""), not leaked)

user = json.dumps({"username": f"d_{random.randint(100000, 999999)}", "password": "password123"}).encode()
request("POST", "/api/register", user)
status, headers, _ = request("POST", "/api/login", user)
cookie = next((c for c in headers.get_all("Set-Cookie") or [] if c.startswith("session=")), "")
flags = cookie.lower()
check("登录成功，会话 Cookie 带 HttpOnly 和 SameSite", status == 200 and "httponly" in flags and "samesite" in flags)
if HTTPS:
    check("用 HTTPS 访问时，会话 Cookie 带 Secure", "secure" in flags)
else:
    print("- 现在用的是 http，跳过 Secure 检查；部署到 HTTPS 后再运行一次")

total = 8 if HTTPS else 7
print(f"\\n通过 {passed} / {total}")`,explain:[{at:'import json',to:'import urllib.request',text:'只用 Python 自带的模块，服务器上也能直接运行。'},{at:'BASE = (sys.argv[1]',to:'passed = 0',text:'服务地址可以从命令行传进来，默认是本地；地址以 https:// 开头时，会多检查一项。'},{at:'def check(name, ok):',to:'passed += bool(ok)',text:'检查一项并打印结果。'},{at:'def request(method, path, data=None):',to:'sys.exit(f"连不上 {BASE}',text:'发请求的小工具：返回状态码、响应头和原始的正文字节（有的检查要看文件内容，不能当文字解码）。连不上时直接退出并提示。'},{at:'def as_json(body):',to:'return None',text:'正文能解析成 JSON 就返回，不能就返回 None。'},{at:'start = time.perf_counter()',to:'check("响应带上了 X-Request-Id',text:'健康检查：状态码、内容，还要够快（平台一般几秒没响应就认为挂了）。X-Request-Id 是第 5 关加的请求编号。'},{at:'status, headers, body = request("GET", "/")',to:'check("首页能打开"',text:'首页返回 HTML。'},{at:'status, headers, body = request("GET", "/api/no-such-thing")',to:'check("不存在的接口返回 404 和 JSON 错误"',text:'不存在的接口返回 404 和 JSON，而不是一大段报错页面。'},{at:'status, _, body = request("POST", "/api/login", b"{not json")',to:'check("格式错误的请求返回 400，不是 500"',text:'客户端发来乱七八糟的内容是客户端的错（400），不能让服务器报 500。'},{at:'leaked = []',to:'leaked.append(path)',text:'试着下载几个不该公开的文件：返回 200 并且内容像 SQLite 数据库（文件以 SQLite format 3 开头）、git 配置或者密钥文件，就算泄露。'},{at:'check("下载不到数据库文件',text:'一个都没泄露才算通过，泄露了会列出是哪几个地址。'},{at:'user = json.dumps(',to:'flags = cookie.lower()',text:'注册一个随机用户并登录，从响应头里找出 session 那个 Set-Cookie（get_all 取出所有同名的头）。'},{at:'check("登录成功，会话 Cookie 带 HttpOnly 和 SameSite"',text:'HttpOnly 让 JavaScript 读不到 Cookie，SameSite 防止别的网站带着它发请求（第 9 关）。'},{at:'if HTTPS:',to:'print("- 现在用的是 http',text:'用 HTTPS 访问时检查 Secure；本地用 http 时跳过这一项。'},{at:'total = 8 if HTTPS else 7',to:'print(f"\\n通过 {passed} / {total}")',text:'打印总的通过数。'}]},
  {title:'这一关学到了什么',body:'一、开发环境和生产环境用同一份代码，差别全部放在环境变量里，密钥不进代码、不进 Git；\n二、健康检查要真的检查依赖（数据库），不可用时返回 503；\n三、线上用 HTTPS，会话 Cookie 加 Secure；\n四、Docker 把程序和运行环境打包成镜像；多阶段构建让镜像更小；数据放在挂载的文件夹里；\n五、持续集成：每次推送自动跑测试和验收脚本；\n六、部署：服务器 + 域名 + 反向代理自动 HTTPS，定期备份数据。\n恭喜你走完了全部 18 关：从一个“你好”接口开始，亲手做出了一个带登录、复习计划、判题、考试、AI 评分、第三方登录、管理后台、自动化测试，并且部署上线的完整网站。接下来可以继续加你自己想要的功能，或者换一种语言再做一遍，对比它们的异同。'}
 ],quiz:[
 {id:'pj-deploy-1',q:'健康检查发现数据库不可用时，应该返回哪个状态码？',options:['503，服务暂时不可用','200，表示一切正常','404，表示接口不存在','400，表示请求不合法'],why:['','返回 200 平台会以为一切正常，继续把用户送过来。','接口是存在的。','请求本身没有问题。'],answer:0,explain:'503 表示“服务暂时不可用”，部署平台看到它会自动重启或者先不把流量送过来。'},
 {id:'pj-deploy-2',q:'会话 Cookie 加上 Secure 标记以后，会怎样？',options:['浏览器只通过 HTTPS 发送它','JavaScript 读不到这个 Cookie','别的网站不能带着它发请求','Cookie 的内容会被加密保存'],why:['','这是 HttpOnly 的作用。','这是 SameSite 的作用。','Secure 不加密 Cookie 的内容。'],answer:0,explain:'Secure 让浏览器只在 HTTPS 连接上发送这个 Cookie，避免它在 http 连接上以明文传输被人截获。'},
 {id:'pj-deploy-3',type:'judge',q:'AI_API_KEY、GITHUB_CLIENT_SECRET 这类密钥可以写在 Dockerfile 的 ENV 里，这样部署时就不用再设置了。',answer:false,explain:'错误。写进 Dockerfile 就会进入 Git 仓库和镜像，任何拿到它们的人都能看到。密钥要在运行容器时通过环境变量或环境变量文件传入。'},
 {id:'pj-deploy-4',q:'Docker 的“多阶段构建”主要是为了？',options:['让最终的镜像更小、更干净','让构建的过程更容易出错','把源代码也一起发布出去','同时运行多个不同的容器'],why:['','这不是目的。','正好相反，最终镜像里没有源代码。','运行多个容器和多阶段构建无关。'],answer:0,explain:'第一阶段在有编译工具的镜像里编译，第二阶段只把编译结果复制到一个小镜像里，最终的镜像没有编译器和源代码。'},
 {id:'pj-deploy-5',q:'容器运行时加上 -v /srv/zixishi:/app/db 的作用是？',options:['数据存在服务器上，删容器不丢','把容器的端口开放到服务器上','限制容器最多能用多少内存','让容器每次启动都清空数据'],why:['','开放端口是 -p。','限制内存是 --memory。','正好相反，是为了让数据保留下来。'],answer:0,explain:'-v 把服务器上的文件夹挂载进容器。容器里写到 /app/db 的文件实际保存在服务器的 /srv/zixishi，换容器、升级都不会丢。'},
 {id:'pj-deploy-6',type:'multi',q:'下面哪些文件应该写进 .dockerignore，不打包进镜像？（多选）',options:['本地的数据库文件 *.db','整个 .git 版本库文件夹','node_modules 或 .venv','题目数据 data/questions.json'],why:['','','','服务启动时要从它导入题目，必须打包进去。'],answers:[0,1,2],explain:'本地数据库可能有私人数据；.git 没用还可能泄露历史；依赖在镜像里重新安装。题目数据是程序运行需要的。'},
 {id:'pj-deploy-7',type:'fill',q:'每次推送代码时自动拉取、安装依赖、运行测试的做法，叫持续 ＿。',accepted:['集成','integration','集成（CI）'],explain:'持续集成（CI，Continuous Integration）。测试通过后自动部署叫持续部署（CD）。'},
 {id:'pj-deploy-8',type:'judge',q:'容器的端口映射写成 -p 127.0.0.1:8080:8080，外网就不能绕过 Caddy 直接用 http 访问 8080 端口了。',answer:true,explain:'正确。只绑定到 127.0.0.1，只有服务器自己（Caddy）能连到 8080，外面的人只能通过 Caddy 的 HTTPS 访问。'},
 {id:'pj-deploy-9',type:'short',q:'把项目部署到一台新的云服务器上，大致要做哪几步？请按顺序说明。',reference:'一、买服务器和域名，把域名解析到服务器的公网 IP；二、在服务器上装好 Docker 和 Caddy；三、拉取代码，用 Dockerfile 构建镜像；四、把密钥写进只有自己能读的环境变量文件；五、运行容器：挂载数据库文件夹、只在本机开放端口、传入环境变量；六、配置 Caddy 把域名转给容器，自动申请 HTTPS 证书；七、用验收脚本检查线上地址，并安排定期备份。',points:['域名解析到服务器','构建镜像','密钥放在服务器上的环境变量文件','运行容器并挂载数据目录','反向代理和 HTTPS','上线后验收和备份'],explain:'顺序可以略有不同，关键是：密钥不进代码、数据挂载出来、HTTPS、上线后验证、定期备份。'},
 {id:'pj-deploy-go-1',stack:'go',q:'Go 项目的 Dockerfile 里用 CGO_ENABLED=0 编译，有什么好处？',options:['程序不依赖系统的 C 库，小镜像也能跑','程序运行的速度会快好几倍','编译出来的程序能跑在 Windows 上','可以跳过 go vet 的代码检查'],why:['','速度差别不大。','目标系统由 GOOS 决定，和 CGO 无关。','和 go vet 无关。'],answer:0,explain:'关掉 cgo 后编译出的是“静态”程序，不需要系统里有特定版本的 C 库，放进 alpine 这样的小镜像也能直接运行。我们用的 SQLite 驱动是纯 Go 写的，所以可以关掉。'},
 {id:'pj-deploy-java-1',stack:'java',q:'Java 项目的 Dockerfile 里，为什么先复制 pom.xml 并下载依赖，再复制 src？',options:['依赖没变时，下次构建能用缓存','Maven 要求必须按这个顺序执行','这样打出来的 jar 文件会更小','src 文件夹不能在第一步就复制'],why:['','Maven 没有这个要求。','jar 的大小不受影响。','技术上可以先复制，只是缓存不好用。'],answer:0,explain:'Docker 按步骤缓存。只改了代码、没改 pom.xml 时，下载依赖这一步直接用缓存，构建快很多。'},
 {id:'pj-deploy-node-1',stack:'node',q:'Node.js 的 Dockerfile 里用 npm ci 而不是 npm install，主要因为？',options:['严格按 package-lock.json 安装','它会顺便升级依赖到最新版','它不需要 package.json 文件','它会自动启动服务'],why:['','正好相反，ci 不会改动版本。','两个文件都需要。','安装和启动是两回事。'],answer:0,explain:'npm ci 严格按照锁文件安装，每次装出来的版本完全一样，适合构建镜像和 CI；npm install 可能更新锁文件。'},
 {id:'pj-deploy-python-1',stack:'python',q:'Python 服务在 Docker 容器里，为什么要监听 0.0.0.0 而不是 127.0.0.1？',options:['容器外的请求才能连进来','0.0.0.0 的速度比较快','127.0.0.1 在容器里不存在','这样能自动启用 HTTPS'],why:['','速度一样。','容器里也有 127.0.0.1，只是它指容器自己。','HTTPS 由 Caddy 负责。'],answer:0,explain:'容器有自己的网络。监听 127.0.0.1 只接受容器内部的请求，-p 映射进来的请求连不上；0.0.0.0 接受所有网卡上的请求。'}]};
